import hashlib

def hash_key(raw_key):
    return hashlib.sha256(raw_key.encode()).hexdigest()

def verify_key(raw_key, stored_hash):
    return hash_key(raw_key) == stored_hash

def create_key(owner, scopes):
    raw = generate_api_key()
    db.keys.insert_one({
        "hash": hash_key(raw),
        "owner": owner,
        "scopes": scopes,
        "created_at": now(),
    })
    return raw  # shown once, then discarded

def verify_request(raw_key):
    record = db.keys.find_one({"hash": hash_key(raw_key)})
    if not record or record.get("revoked"):
        raise AuthError("invalid or revoked key")
    return record

def check_rate_limit(key_id):
    count = redis.incr(f"rl:{key_id}:{current_minute()}")
    if count > MAX_PER_MINUTE:
        raise RateLimitError("too many requests for this key")

def log_key_usage(key_record, tool_name):
    logger.info("key_used", key_id=key_record["id"], tool=tool_name, at=now())
    # never log key_record["hash"] or the raw key

def create_client_key(client_name):
    raw = generate_api_key("sk_analytics")
    db.keys.insert_one({
        "hash": hash_key(raw),
        "client": client_name,
        "scopes": ["reports:read"],
        "created_at": now(),
        "revoked": False,
    })
    return raw

def authenticate(raw_key):
    record = db.keys.find_one({"hash": hash_key(raw_key)})
    if not record or record["revoked"]:
        raise AuthError("invalid key")
    return record
